/*common.mpiv.selectRqdtDelayReasonPopList*/
SELECT
	RQDT.QUOTATION_NO
	,RQDT.DELAY_REASON_CODE
	,RQDT.DELAY_RESION_NOTE
	,RQDT.DELAY_SEND_MAIL_FLAG
	,RQDT.DELAY_USER_ID
	,RQDT.DELAY_DATE
	FROM KEPRQDT RQDT
WHERE RQDT.BUYER = #{st_buyer}
AND RQDT.QUOTATION_NO = #{st_quotation_no}
AND RQDT.QUOTATION_SEQ = #{st_quotation_seq}
AND RQDT.REVISION = #{st_revision}

mapper.update:

/*updateMasterMpIvQuotationSendDelayReasonPop*/
UPDATE KEPRQDT RQDT
	SET DELAY_REASON_CODE =#{st_reason_code}
	, DELAY_RESION_NOTE = #{st_reason_remark}
	, DELAY_SEND_MAIL_FLAG =#{st_mail_yn}
	, DELAY_USER_ID = #{st_kep_user_id}
	, DELAY_DATE = SYSDATE
WHERE RQDT.BUYER = #{st_buyer}
AND RQDT.QUOTATION_NO = #{st_quotation_no}
AND RQDT.QUOTATION_SEQ = #{st_quotation_seq}
AND RQDT.REVISION = #{st_revision}

mapper.select:
/*common.mpiv.selectRqdtDelayDetailPop*/ SELECT CASE WHEN RECV_FLAG = 'NW' THEN CASE WHEN ITEM_CHG_REQ_DATE IS NOT NULL AND ITEM_MD_DATE IS NULL THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'DM04' AND CODE = ITEM_MD_REQ_TYPE) ||' 확인 진행중' ELSE '품목정보 및 취급 협력사 확인 진행중' END WHEN RECV_FLAG = 'GA' THEN CASE WHEN AFTER_ITEM_CHG_REQ_DATE IS NOT NULL AND AFTER_ITEM_MD_DATE IS NULL THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'DM04' AND CODE = AFTER_ITEM_MD_REQ_TYPE) ||' 확인 진행중' ELSE CASE WHEN NEGO_ITEM_CHG_REQ_DATE IS NOT NULL AND NEGO_ITEM_MD_DATE IS NULL THEN (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'DM04' AND CODE = NEGO_ITEM_MD_REQ_TYPE) ||' 확인 진행중' ELSE CASE WHEN BID_SUCCESS_FLAG = 'N' THEN CASE WHEN AGENT_REVISION = 1 THEN '견적 접수 지연' WHEN AGENT_REVISION > 1 THEN AGENT_REVISION || '차 견적 진행중' END WHEN BID_SUCCESS_FLAG = 'Y' THEN CASE WHEN ATOB_SEND_FLAG = 'N' THEN '견적 검증 진행중' WHEN ATOB_SEND_FLAG = 'Y' AND ATOB_UNIT_PRICE <> 0 THEN '제출완료' ELSE '견적 접수 지연' END END END END WHEN RECV_FLAG = 'PM' THEN '견적 제출 준비중' ELSE '' END RETURN_VALUE FROM (
SELECT A.RECV_FLAG, A.ATOB_UNIT_PRICE, A.ATOB_SEND_FLAG, (SELECT ITEM_MD_REQ_DATE FROM KEP_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS ITEM_CHG_REQ_DATE, (SELECT ITEM_MD_DATE FROM KEP_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C' AND ITEM_MD_REVISION = (SELECT MAX(ITEM_MD_REVISION) FROM KEP_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C')) AS ITEM_MD_DATE, (SELECT ITEM_MD_REQ_TYPE FROM KEP_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS ITEM_MD_REQ_TYPE, (SELECT ITEM_MD_REQ_DATE FROM KEP_AFTER_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS AFTER_ITEM_CHG_REQ_DATE, (SELECT ITEM_MD_DATE FROM KEP_AFTER_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C' AND ITEM_MD_REVISION = (SELECT MAX(ITEM_MD_REVISION) FROM KEP_AFTER_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C')) AS AFTER_ITEM_MD_DATE, (SELECT ITEM_MD_REQ_TYPE FROM KEP_AFTER_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS AFTER_ITEM_MD_REQ_TYPE, (SELECT ITEM_MD_REQ_DATE FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_CHG_REQ_DATE, (SELECT ITEM_MD_DATE FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C' AND ITEM_MD_REVISION = (SELECT MAX(ITEM_MD_REVISION) FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C')) AS NEGO_ITEM_MD_DATE, (SELECT ITEM_MD_REQ_TYPE FROM KEP_NEGO_ITEM_MD_REQ WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND ITEM_MD_STATUS = 'C') AS NEGO_ITEM_MD_REQ_TYPE, (SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM KEPQTDT WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND STATUS = 'C' AND BID_SUCCESS_FLAG = 'Y') AS BID_SUCCESS_FLAG, (SELECT MAX(AGENT_REVISION) FROM KEPQTDT WHERE BUYER = A.BUYER AND QUOTATION_NO = A.QUOTATION_NO AND QUOTATION_SEQ = A.QUOTATION_SEQ AND REVISION = A.REVISION AND STATUS = 'C') AS AGENT_REVISION FROM KEPRQDT A WHERE 1=1 AND A.BUYER = #{st_buyer} AND A.QUOTATION_NO = #{st_quotation_no} AND A.QUOTATION_SEQ = #{st_quotation_seq} AND A.REVISION = #{st_revision}
)
